import { useState, useEffect } from 'react'
import 'primereact/resources/themes/lara-light-blue/theme.css';
import 'primereact/resources/primereact.min.css';
import { Card } from 'primereact/card'
import { Button } from 'primereact/button'
import { DataTable } from 'primereact/datatable'
import { Column } from 'primereact/column'
import { Calendar } from 'primereact/calendar'
import { Dropdown } from 'primereact/dropdown'
import { Dialog } from 'primereact/dialog'
import { InputText } from 'primereact/inputtext'
import { Menubar } from 'primereact/menubar'
import './home.css'
import './flags.css'
import './menubar.css'

export default function Home() {
    const [consultas, setConsultas] = useState([
        { id: 1, data: new Date('2024-01-15'), medico: 'Dr. Silva', especialidade: 'Cardiologia', status: 'Agendada' },
        { id: 2, data: new Date('2024-01-20'), medico: 'Dra. Santos', especialidade: 'Dermatologia', status: 'Confirmada' }
    ])

    const [showDialog, setShowDialog] = useState(false)
    const [novaConsulta, setNovaConsulta] = useState({
        data: null,
        medico: '',
        especialidade: ''
    })

    const especialidades = [
        { label: 'Cardiologia', value: 'Cardiologia' },
        { label: 'Dermatologia', value: 'Dermatologia' },
        { label: 'Pediatria', value: 'Pediatria' },
        { label: 'Ortopedia', value: 'Ortopedia' }
    ]

    const medicos = [
        { label: 'Dr. Silva', value: 'Dr. Silva' },
        { label: 'Dra. Santos', value: 'Dra. Santos' },
        { label: 'Dr. Costa', value: 'Dr. Costa' },
        { label: 'Dra. Lima', value: 'Dra. Lima' }
    ]

    const handleAgendarConsulta = () => {
        if (novaConsulta.data && novaConsulta.medico && novaConsulta.especialidade) {
            const newId = consultas.length + 1
            setConsultas([...consultas, {
                id: newId,
                data: novaConsulta.data,
                medico: novaConsulta.medico,
                especialidade: novaConsulta.especialidade,
                status: 'Agendada'
            }])
            setNovaConsulta({ data: null, medico: '', especialidade: '' })
            setShowDialog(false)
        }
    }

    const formatDate = (date) => {
        return date.toLocaleDateString('pt-BR')
    }

    const dateBodyTemplate = (rowData) => {
        return formatDate(rowData.data)
    }

    return (
        <div className="page-container">
            <Card title="MEDSCAN - Home" className="form-card" style={{ maxWidth: '800px' }}>
                <div className="form-content">

                    <p>Gerencie suas consultas médicas de forma simples e rápida.</p>
                    <Card title="Bem-vindo ao MEDSCAN">
                        <p className="m-0" style={{ marginTop: '1rem' }}>
                            Lorem ipsum dolor sit amet, consectetur adipisicing elit. Inventore sed consequuntur error repudiandae 
                            numquam deserunt quisquam repellat libero asperiores earum nam nobis, culpa ratione quam perferendis esse, cupiditate neque quas!
                        </p>
                          <Button label="Ler mais" rounded  style={{ backgroundColor: '#08839B' }} />
                    </Card>

                    <h4>Hospitais por perto</h4>
                    <DataTable value={consultas} responsiveLayout="scroll">
                        <Column field="data" header="Data" body={dateBodyTemplate}></Column>
                        <Column field="medico" header="Médico"></Column>
                        <Column field="especialidade" header="Especialidade"></Column>
                        <Column field="status" header="Status"></Column>
                    </DataTable>
                </div>
            </Card>

            <Dialog 
                header="Agendar Consulta" 
                visible={showDialog} 
                style={{ width: '400px' }} 
                onHide={() => setShowDialog(false)}
            >
                <div className="form-content">
                    <span className="p-float-label" style={{ marginBottom: '1rem' }}>
                        <Calendar 
                            id="data" 
                            value={novaConsulta.data} 
                            onChange={(e) => setNovaConsulta({...novaConsulta, data: e.value})}
                            dateFormat="dd/mm/yy"
                            minDate={new Date()}
                        />
                        <label htmlFor="data">Data da Consulta</label>
                    </span>

                    <span className="p-float-label" style={{ marginBottom: '1rem' }}>
                        <Dropdown 
                            id="especialidade" 
                            value={novaConsulta.especialidade} 
                            onChange={(e) => setNovaConsulta({...novaConsulta, especialidade: e.value})}
                            options={especialidades}
                        />
                        <label htmlFor="especialidade">Especialidade</label>
                    </span>

                    <span className="p-float-label" style={{ marginBottom: '1rem' }}>
                        <Dropdown 
                            id="medico" 
                            value={novaConsulta.medico} 
                            onChange={(e) => setNovaConsulta({...novaConsulta, medico: e.value})}
                            options={medicos}
                        />
                        <label htmlFor="medico">Médico</label>
                    </span>

                    <Button 
                        label="Agendar" 
                        onClick={handleAgendarConsulta}
                        className="p-button-success"
                    />
                </div>
            </Dialog>
            <Menubar/>

        </div>
    )
}

